contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }

	function check(uint256 amount) public {
		require(address(this).balance >= amount, "insufficient balance");
		bool ok;
		(ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));
		// P reverts because the target call fails; M swallows the failure and succeeds.
		assert(!ok);
	}

	receive() external payable {}
	fallback() external payable {}
}

contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }

	function test(uint256 a, uint256 b) public {
		require(a > 0 && b > 0);
		require(address(this).balance >= a + b);
		uint256 before = address(this).balance + address(c).balance;

		payable(address(c)).transfer(b); // c now holds surplus b via fallback
		c.go{value: a}();

		assert(address(this).balance == before - a);
	}

	receive() external payable {}
	fallback() external payable {}
}

